// Generates supabase/catalog.sql from src/data/collections.js so the server
// knows every series, figure, price and value. Run: npm run gen:catalog
import { writeFileSync } from 'node:fs'
import { PARTS, TRACKS, UPGRADE_BOX_PRICE } from '../src/data/cars.js'
import { minTimeMs } from '../src/race/trackGeometry.js'
import { ALL_SERIES as SERIES, DAILY_ALLOWANCE, STARTING_WALLET, WELCOME_BONUS, BANK_RATE, PUZZLE_REWARDS, WHEEL_PRIZES } from '../src/data/collections.js'

const q = (s) => `'${String(s).replace(/'/g, "''")}'`
const lines = [
  '-- Generated by scripts/gen-catalog.mjs — do not edit by hand.',
  '-- Re-run this file in the Supabase SQL editor after changing collections.js.',
  'begin;',
  `insert into public.game_config (id, starting_wallet, daily_allowance, welcome_bonus, bank_rate, puzzle_small, puzzle_medium, puzzle_large)`,
  `  values (1, ${STARTING_WALLET}, ${DAILY_ALLOWANCE}, ${WELCOME_BONUS}, ${BANK_RATE}, ${PUZZLE_REWARDS.small}, ${PUZZLE_REWARDS.medium}, ${PUZZLE_REWARDS.large})`,
  '  on conflict (id) do update set starting_wallet = excluded.starting_wallet, daily_allowance = excluded.daily_allowance,',
  '    welcome_bonus = excluded.welcome_bonus, bank_rate = excluded.bank_rate, puzzle_small = excluded.puzzle_small,',
  '    puzzle_medium = excluded.puzzle_medium, puzzle_large = excluded.puzzle_large;',
]
for (const s of SERIES) {
  lines.push(
    `insert into public.series (id, price, secret_odds, brand) values (${q(s.id)}, ${s.price}, ${s.odds}, ${q(s.brand)})`,
    '  on conflict (id) do update set price = excluded.price, secret_odds = excluded.secret_odds, brand = excluded.brand;',
  )
  for (const f of [...s.figures, s.secret]) {
    // cars also carry their race stats
    const st = f.stats ? [f.stats.speed, f.stats.accel, f.stats.grip, f.stats.weight].join(', ') : 'null, null, null, null'
    lines.push(
      `insert into public.figures (id, series_id, value, secret, speed, accel, grip, weight) values (${q(f.id)}, ${q(s.id)}, ${f.value}, ${f.secret}, ${st})`,
      '  on conflict (id) do update set series_id = excluded.series_id, value = excluded.value, secret = excluded.secret,',
      '    speed = excluded.speed, accel = excluded.accel, grip = excluded.grip, weight = excluded.weight;',
    )
  }
}
for (const t of TRACKS) {
  const w = t.weights
  const r = t.risk
  lines.push(
    // min_ms: the fastest time trial anyone could drive (the server refuses faster times)
    `insert into public.tracks (id, w_speed, w_accel, w_grip, w_weight, risk_stat, risk_below, risk_chance, min_ms) values (${q(t.id)}, ${w.speed}, ${w.accel}, ${w.grip}, ${w.weight}, ${r ? q(r.stat) : 'null'}, ${r ? r.below : 'null'}, ${r ? r.chance : 'null'}, ${minTimeMs(t.id)})`,
    '  on conflict (id) do update set w_speed = excluded.w_speed, w_accel = excluded.w_accel, w_grip = excluded.w_grip, w_weight = excluded.w_weight,',
    '    risk_stat = excluded.risk_stat, risk_below = excluded.risk_below, risk_chance = excluded.risk_chance, min_ms = excluded.min_ms;',
  )
}
// upgrade boxes: the price and the parts that can come out
lines.push(`update public.game_config set upgrade_box_price = ${UPGRADE_BOX_PRICE};`)
for (const p of PARTS) {
  const b = { speed: 0, accel: 0, grip: 0, weight: 0, ...p.bonus }
  lines.push(
    `insert into public.upgrade_parts (id, speed, accel, grip, weight, draw) values (${q(p.id)}, ${b.speed}, ${b.accel}, ${b.grip}, ${b.weight}, ${p.draw})`,
    '  on conflict (id) do update set speed = excluded.speed, accel = excluded.accel, grip = excluded.grip, weight = excluded.weight, draw = excluded.draw;',
  )
}
lines.push('delete from public.wheel_prizes;')
WHEEL_PRIZES.forEach((p, i) => {
  lines.push(
    `insert into public.wheel_prizes (key, kind, amount, count, weight, sort) values (${q(p.key)}, ${q(p.kind)}, ${p.amount ?? 'null'}, ${p.count ?? 'null'}, ${p.weight}, ${i});`,
  )
})
lines.push('commit;', '')
writeFileSync(new URL('../supabase/catalog.sql', import.meta.url), lines.join('\n'))
console.log(`Wrote catalog for ${SERIES.length} series`)
